import sys


def run_solution(input_data):
    result = subprocess.run(
        [sys.executable, "solution.py"],
        input=repr(input_data),
        text=True,
        capture_output=True,
        check=True,
    )
    return result.stdout.splitlines()

def test_basic_username_password_verification():
    data = {
        "add": [("circle", "cat")],
        "verify": [
            ("circle", "cat"),
            ("circle", "dog"),
            ("cat", "cat"),
        ],
    }
    assert run_solution(data) == ["True", "False", "False"]

def test_readding_user_replaces_password():
    data = {
        "add": [("user", "old"), ("user", "new")],
        "verify": [("user", "new"), ("user", "old")],
    }
    assert run_solution(data) == ["True", "False"]

