import subprocess
import sys
import pytest


def run_solution(value):
    return subprocess.run(
        [sys.executable, "solution.py"],
        input=value + "\n",
        text=True,
        capture_output=True,
        check=False,
    )

@pytest.mark.parametrize(
    ("value", "expected"),
    [
        ("a,b,c", "c,b,a\n"),
        ("single", "single\n"),
        ("", "\n"),
    ],
)
def test_reverse_comma_separated_values(value, expected):
    result = run_solution(value)
    assert result.returncode == 0
    assert result.stdout == expected

